def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = {}
        hits = 0
        misses = 0

        def cache_clear():
            nonlocal cache
            cache = {}

        def get_cache_key(*args, **kwargs):
            if typed:
                key = args
            else:
                key = tuple(a if isinstance(a, type) else a for a in args)
            if kwargs:
                key = key + tuple(sorted(kwargs.items(), key=lambda item: item[0]))
            return key

        def cache_get(*args, **kwargs):
            key = get_cache_key(*args, **kwargs)
            if key in cache:
                value, timestamp = cache[key]
                if timer() - timestamp < ttl:
                    return value
                del cache[key]
            return None

        def cache_set(key, value):
            cache[key] = (value, timer())
            if len(cache) > maxsize:
                oldest_key = min(cache, key=lambda k: cache[k][1])
                del cache[oldest_key]

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            value = cache_get(*args, **kwargs)
            if value is not None:
                hits += 1
                return value
            misses += 1
            result = func(*args, **kwargs)
            key = get_cache_key(*args, **kwargs)
            cache_set(key, result)
            return result

        wrapper.cache_info = lambda: (hits, misses, len(cache))
        wrapper.cache_clear = cache_clear
        return wrapper
    return decorator

def mru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = OrderedDict()
        cache.setdefault = cache.get
        lock = RLock()
        if typed:
            def keyfunc(*args, **kwargs):
                return (*args, frozenset(kwargs.items()))
        else:
            def keyfunc(*args, **kwargs):
                return args, frozenset(kwargs.items())
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = keyfunc(*args, **kwargs)
            with lock:
                try:
                    result = cache[key][0]
                    cache.move_to_end(key)
                    return result
                except KeyError:
                    pass
            result = func(*args, **kwargs)
            with lock:
                if len(cache) == maxsize:
                    cache.popitem(last=False)
                cache[key] = (result, lock)
            return result
        def cache_clear():
            with lock:
                cache.clear()
        wrapper.cache_clear = cache_clear
        wrapper.cache_info = cache_info if hasattr(cache, 'cache_info') else lambda: (0, 0, 0)
        return wrapper
    return decorator

