def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    cmd = []
    if isinstance(commands, str):
        commands = [commands]
    for command in commands:
        for arg in args:
            if arg.startswith("{command}"):
                cmd.append(arg.replace("{command}", command))
            else:
                cmd.append(arg)
    if commands and not args:
        cmd = [commands[0]]
    if cwd is None:
        cwd = os.getcwd()
    if verbose:
        print("Running command: " + " ".join(cmd))
    p = subprocess.Popen(cmd, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=(subprocess.PIPE if not hide_stderr else None))
    output = p.communicate()
    if verbose:
        print(output[0])
    return p

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    warnings = []

    def walk_hierarchy(obj, path):
        nonlocal num_objects, good_objects
        num_objects += 1
        is_valid = True

        if validate_objects:
            if not self._is_object_valid(obj):
                is_valid = False
                if show_warnings:
                    warnings.append(f"Invalid object at {path}")

        if is_valid and check_digests:
            digest = self._compute_digest(obj)
            if digest != obj.digest:
                is_valid = False
                if show_warnings:
                    warnings.append(f"Digest mismatch at {path}")

        if is_valid:
            good_objects += 1

        if hasattr(obj, 'children') and isinstance(obj.children, list):
            for child in obj.children:
                walk_hierarchy(child, f"{path}/{child.name}")

    walk_hierarchy(self.root, "/")

    if show_warnings and warnings:
        for warning in warnings:
            print(warning)

    return num_objects, good_objects

