def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    for version_dir in version_dirs:
        inventory_path = os.path.join(self.versions_dir, version_dir, INVENTORY_FILENAME)
        if not os.path.isfile(inventory_path):
            # No inventory for this version, which is allowed but we log it
            continue

        try:
            with open(inventory_path, 'r') as f:
                inventory_data = json.load(f)
        except (json.JSONDecodeError, IOError):
            # Failed to read or parse inventory, we might want to warn but continue
            continue

        if not isinstance(inventory_data, dict):
            continue

        # Ensure each inventory has the necessary fields
        if 'entries' not in inventory_data:
            continue

        entries = inventory_data.get('entries', [])
        if not isinstance(entries, list):
            continue

        # Keep a record of content digests not in root inventory
        for entry in entries:
            if not isinstance(entry, dict):
                continue
            path = entry.get('path')
            digests = entry.get('digests', {})
            if path and digests:
                self.version_content_digests.setdefault(path, set()).update(digests.values())

