def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if filename is None:
        filename = os.path.basename(archive_path)

    # Determine the extension to decide how to extract
    lower_filename = filename.lower()

    tmp_dir = Path(tmp_path)
    tmp_dir.mkdir(parents=True, exist_ok=True)

    # Generate a unique destination directory
    dest_dir = tmp_dir / f"repo_extract_{os.path.getmtime(archive_path)}"

    # If a file with the same name exists, extract to a subdirectory
    if os.path.exists(dest_dir):
        import shutil
        shutil.rmtree(dest_dir)

    dest_dir.mkdir(parents=True, exist_ok=True)

    try:
        if lower_filename.endswith('.tar'):
            subprocess.run(['tar', '-xf', archive_path, '-C', str(dest_dir)], check=True, capture_output=True)
        elif lower_filename.endswith(('.tar.gz', '.tgz', '.tar.bz2', '.tbz2')):
            subprocess.run(['tar', '-xf', archive_path, '-C', str(dest_dir)], check=True, capture_output=True)
        elif lower_filename.endswith(('.zip',)):
            subprocess.run(['unzip', '-o', archive_path, '-d', str(dest_dir)], check=True, capture_output=True)
        else:
            # Default to tar if unknown, or raise an error
            # For this context, let's assume it might be a tarball or try generic extraction
            try:
                subprocess.run(['tar', '-xf', archive_path, '-C', str(dest_dir)], check=True, capture_output=True)
            except subprocess.CalledProcessError:
                try:
                    subprocess.run(['unzip', '-o', archive_path, '-d', str(dest_dir)], check=True, capture_output=True)
                except subprocess.CalledProcessError:
                    raise Exception(f"Unsupported archive format: {filename}")
    except subprocess.CalledProcessError as e:
        raise Exception(f"Failed to extract archive: {e.stderr.decode() if e.stderr else str(e)}")

    # Return the file url
    # Usually checkouts require a specific path inside
    return f"file://{str(dest_dir)}"

