def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        metaclasses = [explicit_mc] + [b.__class__ for b in bases]
    else:
        metaclasses = [b.__class__ for b in bases]

    metaclasses = list(set(metaclasses))

    if len(metaclasses) == 1:
        return metaclasses[0]

    # If there's more than one clear winner based on type inheritance
    def _wins(metaclass):
        return all(issubclass(other, metaclass) for other in metaclasses)

    for metaclass in metaclasses:
        if _wins(metaclass):
            return metaclass

    raise TypeError(
        "Error when finding the metaclass of%s: "
        "Multiple inheritances of type-classes and non-type-classes "
        "are not yet supported" % (bases))

