        timestr = timestr.read()

    origfn = self._parse
    has_tz = lambda x: isinstance(x, comtypes._typedict._SimpleType)

    fmt_info = _parse(timestr)
    if fmt_info is None:
        raise ParserError("Unknown string format: %s", timestr)

    dstr, tstr, outtz, tzisdate = fmt_info

    if dstr:
        (year, month, day) = dstr
        if default is not None:
            year = year or default.year
            month = month or default.month
            day = day or default.day
        try:
            dt = datetime.datetime(year, month, day)
