            if ignoretz and dt.tzinfo:
                raise ValueError('default has tzinfo.')

    if tstr:
        (hour, minute, second, microsecond) = tstr
        hour = hour or dt.hour
        minute = minute or dt.minute
        second = second or dt.second
        microsecond = microsecond or dt.microsecond
        try:
            dt = dt.replace(hour=hour, minute=minute, second=second, microsecond=microsecond)
        except ValueError as e:
            raise ParserError(str(e) + " from timestr: %s", tstr)

    if not ignoretz:
        if outtz is not None:
            if tzinfos is not None:
                tz = _resolve_tz(outtz, tzinfos)
                dt = dt.replace(tzinfo=tz)
            else:
                try:
                    tz = _get_tzinfo(outtz)
                    dt = dt.replace(tzinfo=tz)
                except ValueError as e:
                    raise ParserError(str(e) + " from timestr: %s", timestr)

    return dt

