def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Check if document is JSON (starts with { or [)
    stripped = document.strip()
    if stripped.startswith("{") or stripped.startswith("["):
        # Try parsing as JSON
        try:
            data = json.loads(document)
            if isinstance(data, dict):
                # Look for links in the JSON webfinger response
                links = data.get("links", [])
                result = {"hcard_url": None, "diaspora_url": None, "lid": data.get("subject")}
                for link in links:
                    rel = link.get("rel")
                    if rel == "http://ostatus.me/1.0":
                        result["hcard_url"] = link.get("template") or link.get("href")
                    elif rel == "http://diaspora.org/1.0":
                        result["diaspora_url"] = link.get("template") or link.get("href")
                return result
            elif isinstance(data, list):
                # Maybe it's a list of links
                result = {"hcard_url": None, "diaspora_url": None, "lid": None}
                for link in data:
                    rel = link.get("rel")
                    if rel == "http://ostatus.me/1.0":
                        result["hcard_url"] = link.get("template") or link.get("href")
                    elif rel == "http://diaspora.org/1.0":
                        result["diaspora_url"] = link.get("template") or link.get("href")
                return result
        except json.JSONDecodeError:
            # Fall through to XRD parsing
            pass

    # Try parsing as XRD (XML)
    try:
        root = ET.fromstring(document)
        result = {"hcard_url": None, "diaspora_url": None, "lid": root.get("subject")}

        # Define namespaces
        namespaces = {
            'xrd': 'xri://$xp/type-services/language/xrd/1.0',
            'aliasxrd': 'http://host-meta.diaspora.org/1.0'
        }

        # Find all Link elements
        for link in root.iter():
            local_name = link.tag.split('}')[-1] if '}' in link.tag else link.tag
            if local_name == 'Link':
                rel = link.get('rel')
                href = link.get('href')
                template = link.get('template')
                if rel == 'http://ostatus.me/1.0':
                    result["hcard_url"] = template or href
                elif rel == 'http://diaspora.org/1.0':
                    result["diaspora_url"] = template or href

        return result
    except ET.ParseError:
        # If both fail, return an empty dict or raise an exception
        return {}
